def err_unexpected(arg: str, usage: str, tip: str = None) -> int:
    err(f"error: unexpected argument '{arg}' found")
    if tip:
        err("")
        err(f"  tip: {tip}")
    err("")
    err(f"Usage: {usage}")
    err("")
    err("For more information, try '--help'.")
    return 2


def err_unrecognized_sub(arg: str, usage: str) -> int:
    err(f"error: unrecognized subcommand '{arg}'")
    err("")
    err(f"Usage: {usage}")
    err("")
    err("For more information, try '--help'.")
    return 2


def err_missing_value(opt: str, metavar: str) -> int:
    err(f"error: a value is required for '{opt} <{metavar}>' but none was supplied")
    err("")
    err("For more information, try '--help'.")
    return 2


def has_long_help(args):
