def parse_export(args):
    fmt = "json"
    output = None
    i = 0
    while i < len(args):
        a = args[i]
        if a in ("-h", "--help") or (a.startswith("-") and not a.startswith("--") and "h" in a):
            return ("help", fmt, output, None)
        if a == "--format":
            if i + 1 >= len(args) or args[i+1].startswith("-"):
                return ("missing", fmt, output, ("--format", "FORMAT"))
            fmt = args[i+1]; i += 2; continue
        if a.startswith("--format="):
            fmt = a.split("=", 1)[1]; i += 1; continue
        if a == "--output":
            if i + 1 >= len(args) or args[i+1].startswith("-"):
                return ("missing", fmt, output, ("--output", "OUTPUT"))
            output = args[i+1]; i += 2; continue
        if a.startswith("--output="):
            output = a.split("=", 1)[1]; i += 1; continue
        return ("unexpected", fmt, output, a)
    return ("ok", fmt, output, None)


def command_export(args) -> int:
