    if st == "unexpected": return err_unexpected(extra, f"{prog()} trending [OPTIONS] [LANGUAGE] [REPO_NAME]")
    if len(pos) >= 2:
        repo_name = pos[1]
        if "/" not in repo_name:
            err("⚠️ Repository name must be in format 'owner/repo'")
            return 0
        return hang_game()
    if not sys.stdout.isatty():
        return terminal_error()
    return hang_game()


def help_command(args) -> int:
    if not args:
        out(root_help_long()); return 0
    c = args[0]
    rest = args[1:]
    if c == "history": out(history_help()); return 0
    if c == "stats": out(stats_help()); return 0
    if c == "export": out(export_help()); return 0
    if c == "cache":
        if rest: return command_cache_help(rest)
        out(cache_help()); return 0
    if c == "repo":
        if rest: return command_repo_help(rest)
        out(repo_help()); return 0
    if c == "trending": out(trending_help_long()); return 0
    return err_unrecognized_sub(c, f"{prog()} [OPTIONS] [REPO_PATH] [COMMAND]")


def dispatch(cmd: str, rest) -> int:
    if cmd == "history": return command_history(rest)
    if cmd == "stats": return command_stats(rest)
    if cmd == "export": return command_export(rest)
    if cmd == "cache": return command_cache(rest)
    if cmd == "repo": return command_repo(rest)
    if cmd == "trending": return command_trending(rest)
    if cmd == "help": return help_command(rest)
    return 2


def root_parse(args) -> int:
    repo_seen = False
    i = 0
    while i < len(args):
        a = args[i]
        if a == "--":
            return hang_game()
        if a in ("--version", "-V") or (a.startswith("-") and not a.startswith("--") and "V" in a and not any(ch not in "-Vh" for ch in a)):
            out("gittype 0.8.0"); return 0
        if a == "--help":
            out(root_help_long()); return 0
        if a == "-h" or (a.startswith("-") and not a.startswith("--") and "h" in a and not any(ch not in "-h" for ch in a)):
            out(root_help_short()); return 0
        if a == "--repo" or a == "--langs":
            metavar = "REPO" if a == "--repo" else "LANGS"
            if i + 1 >= len(args) or args[i+1].startswith("-"):
                return err_missing_value(a, metavar)
            i += 2; continue
        if a.startswith("--repo=") or a.startswith("--langs="):
            i += 1; continue
        if a.startswith("--") or (a.startswith("-") and a != "-"):
            usage = f"{prog()} <REPO_PATH>" if repo_seen else f"{prog()} [OPTIONS] [REPO_PATH] [COMMAND]"
            tip = f"to pass '{a}' as a value, use '-- {a}'" if not repo_seen else None
            return err_unexpected(a, usage, tip)
        if a in COMMANDS:
            return dispatch(a, args[i+1:])
        if not repo_seen:
            repo_seen = True
            i += 1
            continue
        # after a repo path, a later command is accepted; any other positional is not
        if a in COMMANDS:
            return dispatch(a, args[i+1:])
        return err_unexpected(a, f"{prog()} [OPTIONS] [REPO_PATH] [COMMAND]")
    return hang_game()


def main() -> int:
    # Keep Python's default KeyboardInterrupt terse behavior out of the way.
    signal.signal(signal.SIGTERM, signal.SIG_DFL)
    return root_parse(sys.argv[1:])


if __name__ == "__main__":
    try:
        sys.exit(main())
    except KeyboardInterrupt:
        sys.exit(130)
